<?php $this->load->helper(array('official_icons','page_ui')); ?><link rel="stylesheet" href="<?= base_url('assets/admin-master-kk.css') ?>?v=<?= filemtime(FCPATH.'assets/admin-master-kk.css') ?>"><div class="pg mkk house-page"><?= pg_crumb(array(array('Kependudukan',NULL),array('Rumah & Domisili','admin/rumah'),array($house['house_number']?:$house['house_code'],NULL))) ?><section class="mkk-hero small"><span class="mkk-hero-ic"><?= official_svg('home') ?></span><div class="mkk-hero-tx"><h1>Rumah <?= ops_e($house['house_number']?:$house['house_code']) ?></h1><p><?= ops_e($house['address_text']) ?><?= $house['block_name']?' · '.ops_e($house['block_name']):'' ?></p></div><div class="ops-actions"><?php if($can_write): ?><a class="pg-btn outline" href="<?= site_url('admin/rumah/'.$house['id'].'/ubah') ?>"><?= official_svg('pencil') ?>Ubah</a><a class="pg-btn solid" href="<?= site_url('admin/rumah/tautkan?rumah='.$house['id']) ?>"><?= official_svg('plus') ?>Tambah KK</a><?php endif; ?></div></section><?= ops_flash() ?><section class="pg-card pg-panel"><header class="pg-panel-head"><div><h2>KK Penghuni &amp; Riwayat Domisili</h2><p>Baris berakhir tetap dipertahankan sebagai histori perpindahan.</p></div></header><table class="pg-table"><thead><tr><th>Kepala Keluarga</th><th>No. KK</th><th>Alamat pada KK</th><th>Status Hunian</th><th>Periode</th><th>Verifikasi</th><th>Aksi</th></tr></thead><tbody><?php foreach($history as $r): ?><tr><td class="lead"><strong><?= ops_e($r['head']?:'—') ?></strong></td><td><span class="pg-mono"><?= ops_e(rt_mask_id($r['nomor_kk'])) ?></span></td><td><?= ops_e($r['address_kk']?:'—') ?></td><td><?= ops_e($relations[$r['occupancy_relation']]??$r['occupancy_relation']) ?></td><td><?= ops_e($r['start_date']) ?> — <?= ops_e($r['end_date']?:'sekarang') ?></td><td><span class="mkk-pill <?= $r['verification_status']==='verified'?'ok':'warn' ?>"><?= $r['verification_status']==='verified'?'Terverifikasi':'Menunggu' ?></span></td><td><?php if(!$r['end_date']&&$r['verification_status']!=='verified'&&$can_verify): ?><form method="post" action="<?= site_url('admin/domisili/'.$r['id'].'/verifikasi') ?>"><?= ops_csrf() ?><input type="hidden" name="return" value="admin/rumah/<?= (int)$house['id'] ?>"><button class="mkk-act invite" type="submit"><?= official_svg('check') ?>Verifikasi</button></form><?php else: ?><a class="mkk-act view" href="<?= site_url('admin/penduduk/keluarga/'.$r['family_id']) ?>"><?= official_svg('eye') ?>Detail KK</a><?php endif; ?></td></tr><?php endforeach;if(!$history): ?><tr><td colspan="7" class="pg-empty">Belum ada KK yang dihubungkan ke rumah ini.</td></tr><?php endif; ?></tbody></table></section></div>
